// ============================================================
// AGENT #4 — REVIEW MANAGEMENT
// Phân loại review tiêu cực, draft câu trả lời, escalate nghiêm trọng
// Input: Danh sách review mới chưa xử lý từ Google Sheets
// ============================================================

const reviews = $input.all().map(item => item.json);

if (!reviews.length) {
  return [{ json: { hasReviews: false, message: 'Không có review mới cần xử lý.' } }];
}

// Phân loại theo theme
const THEMES = {
  'chat_luong':  { keywords: ['hỏng', 'kém', 'dở', 'tệ', 'chất lượng', 'không dùng được', 'fake', 'giả', 'không hiệu quả'],  label: '⚠️ Chất lượng sản phẩm' },
  'giao_hang':  { keywords: ['chậm', 'trễ', 'giao hàng', 'shipping', 'đóng gói', 'hộp bị', 'vỡ', 'bị móp'],               label: '📦 Giao hàng/Đóng gói' },
  'gia_ca':     { keywords: ['đắt', 'giá cao', 'không xứng', 'không đáng', 'mắc'],                                          label: '💰 Giá cả' },
  'dich_vu':    { keywords: ['tư vấn', 'hỗ trợ', 'cs', 'nhân viên', 'thái độ', 'phục vụ', 'không reply'],                 label: '🎧 Dịch vụ khách hàng' },
  'san_pham':   { keywords: ['mô tả không đúng', 'khác ảnh', 'sai màu', 'sai size', 'không như quảng cáo'],                label: '🔍 Sản phẩm không đúng mô tả' }
};

const ESCALATE_TRIGGERS = ['kiện', 'tố cáo', 'lừa đảo', 'báo cơ quan', 'media', 'báo chí', 'công an', '1 sao tất cả'];

const classifiedReviews = reviews.map(r => {
  const content = (r['Nội dung review'] || r['content'] || '').toLowerCase();
  const rating = parseInt(r['Số sao'] || r['rating'] || 1);
  const platform = r['Sàn'] || r['platform'] || 'TikTok';
  const product = r['Sản phẩm'] || r['product'] || 'N/A';
  const reviewId = r['Review ID'] || r['id'] || 'N/A';

  // Detect theme
  let detectedTheme = 'khac';
  let themeLabel = '❓ Khác';
  for (const [key, cfg] of Object.entries(THEMES)) {
    if (cfg.keywords.some(kw => content.includes(kw))) {
      detectedTheme = key;
      themeLabel = cfg.label;
      break;
    }
  }

  // Check if needs escalation
  const needsEscalation = ESCALATE_TRIGGERS.some(t => content.includes(t)) || rating === 1;

  // Severity
  const severity = needsEscalation ? 'ESCALATE' : rating <= 2 ? 'HIGH' : 'MEDIUM';

  return {
    reviewId, platform, product, rating,
    content: r['Nội dung review'] || r['content'] || '',
    theme: detectedTheme,
    themeLabel,
    severity,
    needsEscalation
  };
});

// Group for Claude
const escalations = classifiedReviews.filter(r => r.needsEscalation);
const highPriority = classifiedReviews.filter(r => r.severity === 'HIGH' && !r.needsEscalation);
const normal = classifiedReviews.filter(r => r.severity === 'MEDIUM');

// Build Claude request for batch processing
const systemPrompt = `Bạn là chuyên gia customer service của Hecatech — công ty bán mỹ phẩm, chăm sóc da, xịt khử mùi trên TikTok và Shopee.
Nhiệm vụ:
1. Phân tích từng review tiêu cực
2. Draft câu trả lời phù hợp theo từng theme (chất lượng/giao hàng/giá/dịch vụ)
3. Đề xuất cách xử lý nội bộ

Phong cách trả lời: chân thành, xin lỗi thực tâm, đề xuất giải pháp cụ thể, không copy-paste template cứng nhắc.
Ngôn ngữ: tiếng Việt, thân thiện, professional.`;

const reviewsForClaude = [...escalations, ...highPriority].slice(0, 10); // Max 10 reviews per run

const userPrompt = `XỬ LÝ REVIEW TIÊU CỰC — ${new Date().toLocaleDateString('vi-VN')}

Tổng: ${reviews.length} review mới | Cần escalate: ${escalations.length} | Ưu tiên cao: ${highPriority.length} | Bình thường: ${normal.length}

Danh sách review cần xử lý (${reviewsForClaude.length} review):
${JSON.stringify(reviewsForClaude, null, 2)}

Cho mỗi review, trả về:
1. REPLY DRAFT (dưới 80 từ, đăng ngay lên ${reviewsForClaude[0]?.platform || 'TikTok'})
2. XỬ LÝ NỘI BỘ (giao ai, làm gì trong 24h)
3. ESCALATE (có/không — nếu có, ghi lý do)

Format output:
---
Review #[ID] | [Sản phẩm] | ⭐[Số sao]
📱 REPLY: [câu trả lời]
🔧 NỘI BỘ: [hành động]
🚨 ESCALATE: [có/không]
---`;

return [{
  json: {
    totalReviews: reviews.length,
    escalations: escalations.length,
    highPriority: highPriority.length,
    hasReviews: reviews.length > 0,
    needsAttention: escalations.length > 0 || highPriority.length > 0,
    classifiedReviews,
    claudeRequest: {
      model: 'claude-sonnet-4-6',
      max_tokens: 2000,
      system: systemPrompt,
      messages: [{ role: 'user', content: userPrompt }]
    }
  }
}];

const claudeResponse = $input.first().json;
const replyDrafts = claudeResponse?.content?.[0]?.text || '⚠️ Lỗi phân tích review.';
const reviewData = $('Classify and Draft Replies').first().json;

const header = `📝 REVIEW MANAGEMENT REPORT — ${new Date().toLocaleDateString('vi-VN')}\n\n📊 Tổng quan: ${reviewData.totalReviews} review mới | 🚨 Escalate: ${reviewData.escalations} | ⚠️ Ưu tiên cao: ${reviewData.highPriority}\n\n`;

// Escalation alert (separate message for CS lead)
const escalationMsg = reviewData.escalations > 0
  ? `🚨 CÓ ${reviewData.escalations} REVIEW CẦN ESCALATE NGAY — CS Lead xem và xử lý trong 1 giờ.\n\n`
  : '';

const fullReport = header + escalationMsg + replyDrafts;

return [{
  json: {
    larkCsMessage: { msg_type: 'text', content: { text: fullReport } },
    larkEscalationMessage: reviewData.escalations > 0
      ? { msg_type: 'text', content: { text: `🚨 ESCALATION ALERT\n${fullReport}` } }
      : null,
    needsEscalation: reviewData.escalations > 0
  }
}];
